const artworks = [
 {id:'starry-night',title:'The Starry Night',artist:'Vincent van Gogh',year:'1889',medium:'Oil on canvas',image:'assets/starry-night.jpg',museum:'Museum of Modern Art',source:'https://www.moma.org/collection/works/79802',story:'Van Gogh painted The Starry Night in June 1889 while staying at Saint-Paul-de-Mausole in Saint-Rémy, France. The landscape combines observation with imagination: a quiet village rests beneath a sky that seems alive with movement.',look:'Follow the swirling brushstrokes across the sky. Then notice how the dark cypress connects the earth to the stars.',position:'center'},
 {id:'great-wave',title:'The Great Wave',artist:'Katsushika Hokusai',year:'ca. 1830–32',medium:'Woodblock print',image:'assets/great-wave.jpg',museum:'The Metropolitan Museum of Art',source:'https://www.metmuseum.org/art/collection/search/56353',story:'Under the Wave off Kanagawa, often called The Great Wave, belongs to Hokusai’s series Thirty-six Views of Mount Fuji. This is a woodblock print rather than a painting: an image made to be reproduced from carved blocks. Three boats face the towering wave, while Mount Fuji sits quietly in the distance.',look:'Find the tiny Mount Fuji beneath the wave. Compare its triangular shape with the smaller wave in the foreground.',position:'center'},
 {id:'pearl-earring',title:'Girl with a Pearl Earring',artist:'Johannes Vermeer',year:'ca. 1665',medium:'Oil on canvas',image:'assets/pearl-earring.jpg',museum:'Mauritshuis',source:'https://www.mauritshuis.nl/en/our-collection/artworks/670-girl-with-a-pearl-earring',story:'Vermeer’s famous figure turns toward us against a dark background. The work is a tronie—a study of a character or type, rather than a portrait of an identified person. Her unusual clothing and softly reflected light make the moment feel both intimate and mysterious.',look:'Look closely at the earring. A few touches of light create the illusion of a pearl, without a sharply drawn outline.',position:'center 35%'}
];
const $=s=>document.querySelector(s);
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
function searchArtworks(query){const terms=normalize(query).split(/\s+/);return artworks.filter(a=>terms.every(t=>normalize(`${a.title} ${a.artist} ${a.id==='great-wave'?'Under the Wave off Kanagawa':''}`).includes(t)));}
function render(){const results=searchArtworks($('#search').value);$('#results').innerHTML=results.map((a)=>`<button class="art-card" data-art="${a.id}" aria-label="Discover ${a.title} by ${a.artist}"><div class="image-wrap"><img src="${a.image}" alt="${a.title} by ${a.artist}" style="object-position:${a.position}"><span class="card-number">0${artworks.indexOf(a)+1}</span></div><div class="card-info"><h3>${a.title}</h3><p>${a.artist} · ${a.year}</p><span class="card-arrow" aria-hidden="true">↗</span></div></button>`).join('');$('#count').textContent=`${results.length} artwork${results.length===1?'':'s'}`;$('#empty').hidden=results.length>0;}
function showArtwork(id){const a=artworks.find(a=>a.id===id);if(!a)return;$('#detail-content').innerHTML=`<div class="detail-layout"><div class="detail-image"><img src="${a.image}" alt="${a.title}"></div><div class="detail-text"><p class="eyebrow">BEYOND THE FRAME</p><h2>${a.title}</h2><p class="artist-line">${a.artist}</p><div class="facts"><div><b>Created</b>${a.year}</div><div><b>Medium</b>${a.medium}</div></div><h3>The story</h3><p>${a.story}</p><div class="look"><strong>Take a closer look</strong><p>${a.look}</p></div><a class="source" href="${a.source}" target="_blank" rel="noopener noreferrer">Read more at ${a.museum} ↗</a></div></div>`;if(!$('#detail').open)$('#detail').showModal();}
$('#search').addEventListener('input',render);$('#search-form').addEventListener('submit',e=>{e.preventDefault();render();const r=searchArtworks($('#search').value);if(r.length===1)showArtwork(r[0].id)});$('#reset').onclick=()=>{$('#search').value='';render();$('#search').focus()};$('#results').onclick=e=>{const card=e.target.closest('[data-art]');if(card)showArtwork(card.dataset.art)};
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$('#photo-button').onclick=()=>$('#photo-input').click();$('#retry').onclick=()=>$('#photo-input').click();
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Image could not be read.'));img.src=src})}
// Deliberately lightweight reference comparison, not AI identification.
function signature(img){const canvas=document.createElement('canvas');canvas.width=16;canvas.height=16;const c=canvas.getContext('2d',{willReadFrequently:true});c.fillStyle='#fff';c.fillRect(0,0,16,16);c.drawImage(img,0,0,16,16);const pixels=c.getImageData(0,0,16,16).data;const values=[];for(let i=0;i<pixels.length;i+=4)values.push(pixels[i]/255,pixels[i+1]/255,pixels[i+2]/255);return values;}
let references;
let photoRun=0;
$('#photo-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;e.target.value='';const run=++photoRun;$('#photo-matches').replaceChildren();$('#photo-status').textContent='Comparing your photo with the collection…';$('#photo-preview').removeAttribute('src');if(!$('#photo-dialog').open)$('#photo-dialog').showModal();if(!file.type.startsWith('image/')){$('#photo-status').textContent='Please choose an image file.';return}if(file.size>20*1024*1024){$('#photo-status').textContent='Please choose a photo smaller than 20 MB.';return}const url=URL.createObjectURL(file);try{const img=await loadImage(url);if(run!==photoRun)return;$('#photo-preview').src=url;const input=signature(img);references??=Promise.all(artworks.map(async a=>({a,values:signature(await loadImage(a.image))}))).catch(err=>{references=null;throw err});const refs=await references;if(run!==photoRun)return;const ranked=refs.map(({a,values})=>({a,distance:values.reduce((sum,v,i)=>sum+(v-input[i])**2,0)/values.length})).sort((a,b)=>a.distance-b.distance);const plausible=ranked[0].distance<.085;$('#photo-status').textContent=plausible?'Possible match — does this look like your artwork?':'No confident match. Is your artwork one of these?';$('#photo-matches').innerHTML=ranked.map(({a},i)=>`<button class="match" data-art="${a.id}"><img src="${a.image}" alt=""><span>${a.title}<small>${a.artist}${i===0&&plausible?' · Closest visual match':''}</small></span></button>`).join('');}catch(err){if(run===photoRun)$('#photo-status').textContent='We couldn’t read this photo. Try a JPG, PNG, or WebP image, or search by title.';}finally{URL.revokeObjectURL(url)}});
$('#photo-matches').onclick=e=>{const b=e.target.closest('[data-art]');if(b){$('#photo-dialog').close();showArtwork(b.dataset.art)}};
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_gallery',description:'Search the demo collection by painting title or artist and update visible results.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string')throw new Error('query must be a string');$('#search').value=input.query;render();return searchArtworks(input.query).map(({id,title,artist})=>({id,title,artist}));}})).catch(()=>{});}catch{}}
